  5→describe('ProgressionService', () => {
  6→  let service: ProgressionService;
  7→  let noteDataService: NoteDataService;
  8→
  9→  beforeEach(() => {
 10→    TestBed.configureTestingModule({
 11→      providers: [ProgressionService, NoteDataService],
 12→    });
 13→    service = TestBed.inject(ProgressionService);
 14→    noteDataService = TestBed.inject(NoteDataService);
 15→  });
 16→
 17→  describe('initial state', () => {
 18→    it('should start with open strings (fret 0) as the current pool', () => {
 19→      const pool = service.getCurrentPool();
 20→
 21→      expect(pool.length).toBe(6);
 22→      for (const note of pool) {
 23→        expect(note.fret).toBe(0);
 24→      }
 25→    });
 26→
 27→    it('should match the open string notes from NoteDataService', () => {
 28→      const pool = service.getCurrentPool();
 29→      const expected = noteDataService.getNotesOnFret(0);
 30→
 31→      expect(pool).toEqual(expected);
 32→    });
 33→
 34→    it('should start at fret level 0', () => {
 35→      expect(service.getCurrentFret()).toBe(0);
 36→    });
 37→
 38→    it('should have no shown notes initially', () => {
 39→      expect(service.getShownNoteCount()).toBe(0);
 40→    });
 41→  });
 42→
 43→  describe('drawNote', () => {
 44→    it('should return a note from the current pool', () => {
 45→      const pool = service.getCurrentPool();
 46→      const note = service.drawNote();
 47→
 48→      expect(pool).toContain(note);
 49→    });
 50→
 51→    it('should throw an error when the pool is empty', () => {
 52→      // Access private pool via any-cast to force an empty pool scenario
 53→      (service as any).pool = [];
 54→
 55→      expect(() => service.drawNote()).toThrowError(
 56→        'ProgressionService: pool is empty — cannot draw note',
 57→      );
 58→    });
 59→
 60→    it('should return different notes over multiple calls (statistical check)', () => {
 61→      const notes = new Set<string>();
 62→      for (let i = 0; i < 50; i++) {
 63→        const note = service.drawNote();
 64→        notes.add(`${note.string}-${note.fret}`);
 65→      }
 66→      // With 6 open strings and 50 draws, we should see more than 1 unique note
 67→      expect(notes.size).toBeGreaterThan(1);
 68→    });
 69→
 70→    it('should automatically mark the returned note as shown', () => {
 71→      const note = service.drawNote();
 72→
 73→      expect(service.getShownNoteCount()).toBe(1);
 74→      expect(service.hasBeenShown(note)).toBe(true);
 75→    });
 76→
 77→    it('should expand pool when all notes marked via markNoteAsShown', () => {
 78→      const pool = service.getCurrentPool();
 79→      expect(pool.length).toBe(6);
 80→
 81→      // Mark all notes as shown to trigger expansion
 82→      // We need to force deterministic behavior for this test
 83→      const seen = new Set<string>();
 84→      for (const note of pool) {
 85→        service.markNoteAsShown(note);
 86→        seen.add(`${note.string}-${note.fret}`);
 87→      }
 88→
 89→      // After all notes shown, pool should have expanded
 90→      expect(service.getCurrentFret()).toBe(1);
 91→    });
 92→  });
 93→
 94→  describe('markNoteAsShown', () => {
 95→    it('should track that a note has been shown', () => {
 96→      const pool = service.getCurrentPool();
 97→      service.markNoteAsShown(pool[0]);
 98→
 99→      expect(service.getShownNoteCount()).toBe(1);
100→    });
101→
102→    it('should not double-count the same note shown twice', () => {
103→      const pool = service.getCurrentPool();
104→      const note = pool[0];
105→
106→      service.markNoteAsShown(note);
107→      service.markNoteAsShown(note);
108→
109→      expect(service.getShownNoteCount()).toBe(1);
110→    });
111→
112→    it('should count distinct notes that have been shown', () => {
113→      const pool = service.getCurrentPool();
114→
115→      service.markNoteAsShown(pool[0]);
116→      service.markNoteAsShown(pool[1]);
117→      service.markNoteAsShown(pool[2]);
118→
119→      expect(service.getShownNoteCount()).toBe(3);
120→    });
121→  });
122→
123→  describe('hasBeenShown', () => {
124→    it('should return false for a note that has not been shown', () => {
125→      const pool = service.getCurrentPool();
126→
127→      expect(service.hasBeenShown(pool[0])).toBe(false);
128→    });
129→
130→    it('should return true for a note that has been shown', () => {
131→      const pool = service.getCurrentPool();
132→      service.markNoteAsShown(pool[0]);
133→
134→      expect(service.hasBeenShown(pool[0])).toBe(true);
135→    });
136→
137→    it('should return false after pool expansion resets tracking', () => {
138→      const pool = service.getCurrentPool();
139→
140→      // Mark all notes as shown to trigger expansion
141→      for (const note of pool) {
142→        service.markNoteAsShown(note);
143→      }
144→
145→      // After expansion, previously shown notes should no longer be marked
146→      expect(service.hasBeenShown(pool[0])).toBe(false);
147→    });
148→  });
149→
150→  describe('pool expansion', () => {
151→    it('should expand pool when all current notes have been shown', () => {
152→      const openStrings = service.getCurrentPool();
153→      expect(openStrings.length).toBe(6);
154→
155→      // Mark all open string notes as shown
156→      for (const note of openStrings) {
157→        service.markNoteAsShown(note);
158→      }
159→
160→      // Pool should now include fret 1 notes too
161→      const expandedPool = service.getCurrentPool();
162→      const fret1Notes = noteDataService.getNotesOnFret(1);
163→
164→      expect(expandedPool.length).toBe(openStrings.length + fret1Notes.length);
165→      expect(service.getCurrentFret()).toBe(1);
166→    });
167→
168→    it('should keep previously learned notes in the expanded pool', () => {
169→      const openStrings = [...service.getCurrentPool()];
170→
171→      // Mark all open string notes as shown
172→      for (const note of openStrings) {
173→        service.markNoteAsShown(note);
174→      }
175→
176→      const expandedPool = service.getCurrentPool();
